"""Report schema the LLM must produce (validated with Pydantic)."""
import re
from typing import List, Literal

from pydantic import BaseModel, ConfigDict, Field, field_validator

# Fixed text; replaces whatever disclaimer the LLM writes
DISCLAIMER = (
    "This report was generated by an AI system from an automated image classifier. It is not a "
    "diagnosis and must not be used on its own to make clinical decisions. A qualified clinician "
    "must review the image and the patient's clinical findings."
)

# Also used by the API's request/response models
ClassName = Literal["Normal", "Pneumonia", "Tuberculosis"]
Status = Literal["confident", "refer"]

_SENTENCE_END = re.compile(r"(?<=[.!?])\s+")


def count_sentences(text):
    return len([s for s in _SENTENCE_END.split(text.strip()) if s.strip()])


class Report(BaseModel):
    model_config = ConfigDict(extra="forbid")

    predicted_class: ClassName
    calibrated_probability: float = Field(ge=0, le=1, description="Copied exactly from run_classifier")
    status: Status
    summary: str = Field(description="Plain language, 2-3 sentences")
    recommendation: str = Field(min_length=1)
    limitations: List[str] = Field(min_length=1)
    disclaimer: str = Field(min_length=1)

    @field_validator("summary")
    @classmethod
    def two_or_three_sentences(cls, v):
        n = count_sentences(v)
        if not 2 <= n <= 3:
            raise ValueError(f"summary must be 2-3 sentences, got {n}")
        return v
